const raw = $input.first().json;

const workflowName = raw.workflow?.name ?? 'unknown';
const nodeName =
  raw.execution?.lastNodeExecuted ??
  raw.node?.name ??
  'unknown';
const when = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
const executionId = raw.execution?.id ?? '-';
const errorMessage =
  raw.execution?.error?.message ??
  raw.message ??
  '-';

function findBusinessKey(obj, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 5) return null;
  if (obj.order_id) return String(obj.order_id);
  if (obj.merchant_id) return String(obj.merchant_id);
  if (obj.business_key) return String(obj.business_key);
  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const found = findBusinessKey(value, depth + 1);
      if (found) return found;
    }
  }
  return null;
}

function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const businessKey = findBusinessKey(raw) ?? '-';

const text = [
  '<b>H8Mart Ops · Alert</b>',
  '',
  `Workflow: <code>${esc(workflowName)}</code>`,
  `Node: <code>${esc(nodeName)}</code>`,
  `Time (WIB): <code>${esc(when)}</code>`,
  `Business key: <code>${esc(businessKey)}</code>`,
  `Execution: <code>${esc(executionId)}</code>`,
  '',
  `Error: <code>${esc(errorMessage)}</code>`,
].join('\n');

return [{
  json: {
    text,
    workflowName,
    nodeName,
    when,
    businessKey,
    executionId,
    errorMessage,
  },
}];
